mkdir -p bin src test && cat > package.json <<'EOF'
{
  "name": "color-cli",
  "version": "0.1.0",
  "description": "A Node.js CLI that only prints colored output when the terminal supports it",
  "type": "module",
  "bin": {
    "color-cli": "./bin/cli.js"
  },
  "files": [
    "bin",
    "src"
  ],
  "scripts": {
    "start": "node bin/cli.js",
    "test": "node --test"
  },
  "engines": {
    "node": ">=20"
  },
  "license": "MIT"
}
EOF
cat > .gitignore <<'EOF'
node_modules/
*.log
EOF
cat > src/color.js <<'EOF'
// Terminal color detection with no dependencies.
//
// Precedence (highest first):
//   1. --color / --no-color CLI flags
//   2. FORCE_COLOR env var (FORCE_COLOR=0 disables, any other value enables)
//   3. NO_COLOR env var (any non-empty value disables; see https://no-color.org)
//   4. Whether the stream is a TTY whose terminal reports color support
//      (Node's tty.WriteStream#hasColors, which also checks TERM, CI, etc.)

/**
 * Decide whether colored output should be written to `stream`.
 *
 * @param {object} [options]
 * @param {NodeJS.WriteStream} [options.stream=process.stdout]
 * @param {NodeJS.ProcessEnv} [options.env=process.env]
 * @param {string[]} [options.argv=process.argv]
 * @returns {boolean}
 */
export function supportsColor({
  stream = process.stdout,
  env = process.env,
  argv = process.argv,
} = {}) {
  if (argv.includes('--no-color')) return false;
  if (argv.includes('--color')) return true;

  if ('FORCE_COLOR' in env) {
    return env.FORCE_COLOR !== '0' && env.FORCE_COLOR !== 'false';
  }
  if (env.NO_COLOR) return false;

  // Piped or redirected output (files, `| less`, CI logs) is not a TTY.
  if (!stream?.isTTY || typeof stream.hasColors !== 'function') return false;

  return stream.hasColors(env);
}

const CODES = {
  bold: [1, 22],
  dim: [2, 22],
  red: [31, 39],
  green: [32, 39],
  yellow: [33, 39],
  blue: [34, 39],
  cyan: [36, 39],
  gray: [90, 39],
};

/**
 * Create a set of color functions. When color is disabled each function
 * returns its input unchanged, so callers never need to branch.
 *
 * @param {boolean} enabled
 * @returns {Record<keyof typeof CODES, (text: string) => string>}
 */
export function createColors(enabled) {
  const colors = {};
  for (const [name, [open, close]] of Object.entries(CODES)) {
    colors[name] = enabled
      ? (text) => `\x1b[${open}m${text}\x1b[${close}m`
      : (text) => String(text);
  }
  return colors;
}
EOF
cat > bin/cli.js <<'EOF'
#!/usr/bin/env node
import { supportsColor, createColors } from '../src/color.js';

const args = process.argv.slice(2);

if (args.includes('--help') || args.includes('-h')) {
  console.log(`Usage: color-cli [options]

Options:
  --color      Force colored output
  --no-color   Disable colored output
  -h, --help   Show this help

Environment:
  NO_COLOR     Disable colored output when set to a non-empty value
  FORCE_COLOR  Force colored output (FORCE_COLOR=0 disables)`);
  process.exit(0);
}

const out = createColors(supportsColor({ stream: process.stdout }));
const err = createColors(supportsColor({ stream: process.stderr }));

console.log(out.green('✔ Success:'), 'everything worked');
console.log(out.yellow('⚠ Warning:'), 'something to look at');
console.log(out.cyan('ℹ Info:'), out.dim('extra details'));
console.error(err.red('✖ Error:'), 'example message on stderr');
EOF
chmod +x bin/cli.js
cat > test/color.test.js <<'EOF'
import { test } from 'node:test';
import assert from 'node:assert/strict';
import { supportsColor, createColors } from '../src/color.js';

const tty = (hasColors = true) => ({ isTTY: true, hasColors: () => hasColors });
const pipe = { isTTY: false };

test('color enabled on a color-capable TTY', () => {
  assert.equal(supportsColor({ stream: tty(), env: {}, argv: [] }), true);
});

test('color disabled on a TTY without color support', () => {
  assert.equal(supportsColor({ stream: tty(false), env: {}, argv: [] }), false);
});

test('color disabled when output is piped', () => {
  assert.equal(supportsColor({ stream: pipe, env: {}, argv: [] }), false);
});

test('NO_COLOR disables color', () => {
  assert.equal(supportsColor({ stream: tty(), env: { NO_COLOR: '1' }, argv: [] }), false);
});

test('empty NO_COLOR is ignored', () => {
  assert.equal(supportsColor({ stream: tty(), env: { NO_COLOR: '' }, argv: [] }), true);
});

test('FORCE_COLOR enables color even when piped', () => {
  assert.equal(supportsColor({ stream: pipe, env: { FORCE_COLOR: '1' }, argv: [] }), true);
});

test('FORCE_COLOR=0 disables color', () => {
  assert.equal(supportsColor({ stream: tty(), env: { FORCE_COLOR: '0' }, argv: [] }), false);
});

test('CLI flags override environment', () => {
  assert.equal(supportsColor({ stream: tty(), env: { FORCE_COLOR: '1' }, argv: ['--no-color'] }), false);
  assert.equal(supportsColor({ stream: pipe, env: { NO_COLOR: '1' }, argv: ['--color'] }), true);
});

test('createColors wraps text only when enabled', () => {
  assert.equal(createColors(true).red('hi'), '\x1b[31mhi\x1b[39m');
  assert.equal(createColors(false).red('hi'), 'hi');
});
EOF
npm test 2>&1 | tail -12
echo "--- piped:"; node bin/cli.js 2>&1 | cat -v
echo "--- FORCE_COLOR:"; FORCE_COLOR=1 node bin/cli.js 2>&1 | cat -v
echo "--- tty:"; script -qc "node bin/cli.js" /dev/null | cat -v
echo "--- tty + NO_COLOR:"; NO_COLOR=1 script -qc "node bin/cli.js" /dev/null | cat -v

